ValidationRule.errorConditionFormula:
AND(
    RecordType.DeveloperName = "NewOperationalTest",
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ6 本提案合意"),
            OR(
                NOT(INCLUDES(CompletionBasis__c, "6-1:提案内容を理解いただき、方向性の合意をいただいた。")),
                NOT(INCLUDES(CompletionBasis__c, "6-2:NDAが締結でき、お客様から見積提出に必要な情報を取得した。")),
                NOT(INCLUDES(CompletionBasis__c, "6-3:提案内容に基づき見積書の作成を依頼された。"))
            )
        )
    )
)
